import { FilterDataStructure } from 'models/Filters';

import {
  hasActiveSubBrandQuickFilterValue,
  isSubBrandMergedIntoBrandChipPage,
} from '../brandSubBrandQuickFilterPolicy';
import FilterRegistry from '../FilterRegistry/FilterRegistry';

export interface QuickFilterContext {
  fieldKey: string;
  pageName: string;
  appliedFilters: Record<string, string | number>;
  dataFilters?: FilterDataStructure;
}

export type FilterRule = (context: QuickFilterContext) => boolean;

const isAllBaselineFilterValue = (
  value: string | number | null | undefined,
): boolean => {
  if (value == null || value === '') return true;
  if (typeof value === 'string') return value.toUpperCase() === 'ALL';
  return false;
};

const isNotAllFilterValue = (value: unknown): boolean => value !== 'All';

type QuickFilterDependencyContext = {
  pageName: string;
  appliedFilters: Record<string, string | number>;
};

const BASELINE_VALUE_FIELD_KEYS = new Set([
  'region',
  'channel',
  'pack_type',
  'growth_levers',
  'category',
  'non_alcoholic',
]);

function evaluateBrandsQuickFilterDependency({
  pageName,
  appliedFilters,
}: QuickFilterDependencyContext): boolean {
  if (isSubBrandMergedIntoBrandChipPage(pageName)) {
    return (
      !isAllBaselineFilterValue(appliedFilters.brands) ||
      hasActiveSubBrandQuickFilterValue(appliedFilters.sub_brands)
    );
  }
  return appliedFilters.brands !== 'All';
}

function evaluateSubBrandsQuickFilterDependency({
  pageName,
  appliedFilters,
}: QuickFilterDependencyContext): boolean {
  if (isSubBrandMergedIntoBrandChipPage(pageName)) return false;
  return hasActiveSubBrandQuickFilterValue(appliedFilters.sub_brands);
}

function evaluateSkuQuickFilterDependency({
  appliedFilters,
}: QuickFilterDependencyContext): boolean {
  if (isAllBaselineFilterValue(appliedFilters.brands)) {
    return false;
  }
  const sku = appliedFilters.sku;
  return sku != null && sku !== '' && !isAllBaselineFilterValue(sku);
}

const quickFilterDependencyEvaluators: Record<
  string,
  (ctx: QuickFilterDependencyContext) => boolean
> = {
  zone: () => false,
  brands: evaluateBrandsQuickFilterDependency,
  sub_brands: evaluateSubBrandsQuickFilterDependency,
  brands_abi: ({ appliedFilters }) =>
    isNotAllFilterValue(appliedFilters.brands_abi),
  global_brands: ({ appliedFilters }) =>
    isNotAllFilterValue(appliedFilters.global_brands) &&
    !!appliedFilters.global_brands,
  portfolios: ({ appliedFilters }) =>
    isNotAllFilterValue(appliedFilters.portfolios),
  beer_price_segment: ({ appliedFilters }) =>
    isNotAllFilterValue(appliedFilters.beer_price_segment),
  brand_filter_groupings: ({ appliedFilters }) =>
    appliedFilters.brand_filter_groupings === 'Global Brands',
  sku: evaluateSkuQuickFilterDependency,
};

function areQuickFilterDependenciesSatisfied(
  fieldKey: string,
  pageName: string,
  appliedFilters: Record<string, string | number>,
): boolean {
  const evaluator = quickFilterDependencyEvaluators[fieldKey];
  if (evaluator) {
    return evaluator({ pageName, appliedFilters });
  }

  if (BASELINE_VALUE_FIELD_KEYS.has(fieldKey)) {
    return !isAllBaselineFilterValue(appliedFilters[fieldKey]);
  }

  return true;
}

/**
 * QuickFilterEngine
 * Determines which filters should be visible based on business rules
 */
class QuickFilterEngine {
  private static instance: QuickFilterEngine;
  private rules: FilterRule[] = [];
  private readonly availableComponents: string[];

  public constructor(availableComponents: string[]) {
    this.availableComponents = availableComponents;
    this.initializeRules();
  }

  public static getInstance(availableComponents: string[]): QuickFilterEngine {
    if (!QuickFilterEngine.instance) {
      QuickFilterEngine.instance = new QuickFilterEngine(availableComponents);
    }
    return QuickFilterEngine.instance;
  }

  /**
   * Initialize all filter rules
   */
  private initializeRules(): void {
    this.rules = [
      this.isRegisteredInFilterRegistry,
      this.hasQuickFilterComponent,
      this.dependenciesAreSatisfied,
      this.hasAvailableOptions,
    ];
  }

  /**
   * Rule: Field must be registered in the FilterRegistry
   */
  private readonly isRegisteredInFilterRegistry: FilterRule = ({
    fieldKey,
  }) => {
    const registry = FilterRegistry.getInstance();
    return registry.has(fieldKey);
  };

  /**
   * Rule: Field must have a Quick Filter component available
   */
  private readonly hasQuickFilterComponent: FilterRule = ({ fieldKey }) => {
    const registry = FilterRegistry.getInstance();
    const config = registry.get(fieldKey);

    if (config?.metadata?.quickFilter === false) {
      return false;
    }

    return this.availableComponents.includes(fieldKey);
  };

  /**
   * Rule: Dependent filters only appear if their parents are filled
   */
  private readonly dependenciesAreSatisfied: FilterRule = ({
    fieldKey,
    pageName,
    appliedFilters,
  }) => areQuickFilterDependenciesSatisfied(fieldKey, pageName, appliedFilters);

  /**
   * Rule: Field only appears if there are available options
   */
  private readonly hasAvailableOptions: FilterRule = ({
    fieldKey,
    dataFilters,
    appliedFilters,
  }) => {
    if (!dataFilters) return true;

    const registry = FilterRegistry.getInstance();
    const config = registry.get(fieldKey);

    if (!config) return false;

    return config.validator(
      dataFilters,
      appliedFilters[fieldKey],
      appliedFilters,
    );
  };

  /**
   * Apply all rules to a single field
   */
  public validateField(context: QuickFilterContext): boolean {
    return this.rules.every((rule) => rule(context));
  }

  /**
   * Apply all rules to multiple fields
   */
  public filterFields(
    fields: string[],
    context: Omit<QuickFilterContext, 'fieldKey'>,
  ): string[] {
    return fields.filter((fieldKey) => {
      const ruleContext: QuickFilterContext = { ...context, fieldKey };
      return this.validateField(ruleContext);
    });
  }

  /**
   * Add a custom rule dynamically
   */
  public addRule(rule: FilterRule): void {
    this.rules.push(rule);
  }

  /**
   * Get all registered rules
   */
  public getRules(): FilterRule[] {
    return [...this.rules];
  }
}

export default QuickFilterEngine;
